OP = 'private.component_bbox.canonical_full_placement.v1'
COUNT = {'computes': 0}
ROWS = []
CHECKS = {}

class Fallback(Exception):
    pass

def box_values(box):
    if type(box) is not dict or set(box) != {'min', 'max'}:
        raise Fallback('missing/unsupported bounds')
    if type(box['min']) not in (tuple, list) or type(box['max']) not in (tuple, list):
        raise Fallback('unsupported bounds coordinates')
    values = [*box['min'], *box['max']]
    if len(values) != 6 or any(type(v) not in (float, int) or not math.isfinite(v) or abs(v) >= 1e90 for v in values):
        raise Fallback('nonfinite/open bounds')
    if any(values[i] > values[i+3] for i in range(3)):
        raise Fallback('inverted bounds')
    return values

def read_snapshot(tree):
    """Verify each tree and byte object before flattening the same snapshots."""
    seen = {}
    def visit(digest):
        if digest in seen:
            return
        data = read_verified_object(digest)
        t = json.loads(data)
        if t.get('kind') != 'tree':
            raise Fallback('not a tree')
        seen[digest] = t
        for entry in t.get('components', {}).values():
            for kind in ('brep', 'surf'):
                read_verified_object(entry[kind])
        for link in t.get('links', []):
            visit(link['tree'])
    visit(tree)
    # The public flattener's read accessor is replaced only in this private
    # single-thread probe, so every linked read sees a verified root snapshot.
    import cadgen.store.trees as trees
    with mock.patch.object(trees, 'get_tree', side_effect=lambda digest: copy.deepcopy(seen[digest])):
        return flatten_tree(copy.deepcopy(seen[tree]), tree_hash=tree)

def ordered_occurrences(descriptor):
    occs = descriptor.get('occurrences')
    if type(occs) is not list or not 1 <= len(occs) <= 64:
        raise Fallback('occurrence limit')
    lookup = {}
    for occ in occs:
        key = occ.get('id')
        if type(key) is not str or key in lookup:
            raise Fallback('ambiguous occurrence identity')
        lookup[key] = occ
    root = descriptor.get('assembly', {}).get('root')
    if type(root) is not dict:
        raise Fallback('missing root')
    ordered = []
    def visit(node, depth=0):
        if depth > 32 or type(node) is not dict:
            raise Fallback('unsupported hierarchy')
        children = node.get('children', [])
        key = node.get('id')
        if key in lookup and not children:
            ordered.append(lookup[key])
        elif type(children) is list and children:
            # _world_leaves traverses native children with a LIFO stack.
            for child in reversed(children):
                visit(child, depth+1)
        else:
            raise Fallback('unmaterialized hierarchy node')
    visit(root)
    if len(ordered) != len(occs) or len({x['id'] for x in ordered}) != len(occs):
        raise Fallback('hierarchy/occurrence mismatch')
    return ordered

def key_args(entry, transform):
    if type(transform) is not list or len(transform) != 16 or any(type(x) not in (int, float) or not math.isfinite(x) for x in transform):
        raise Fallback('unsupported transform')
    if transform[12:] != [0., 0., 0., 1.]:
        raise Fallback('non-affine transform')
    return (entry['brep'], struct.pack('<16d', *transform))

def candidate(descriptor):
    comps = descriptor.get('components')
    if type(comps) is not dict or not 1 <= len(comps) <= 16:
        raise Fallback('component limit')
    payloads = {}
    total_brep = total_surf = 0
    for entry in comps.values():
        for kind in ('brep', 'surf'):
            digest = entry[kind]
            if digest not in payloads:
                payloads[digest] = read_verified_object(digest)
                if kind == 'brep': total_brep += len(payloads[digest])
                else: total_surf += len(payloads[digest])
    if total_brep > 768 * 1024 or total_surf > 4 * 1024 * 1024:
        raise Fallback('verified byte limit')
    boxes = []
    for occ in ordered_occurrences(descriptor):
        entry = comps[occ['component']]
        args = key_args(entry, occ['transform'])
        def compute():
            COUNT['computes'] += 1
            private = cp._build123d_shape_from_brep_bytes(payloads[entry['brep']])
            placed = private.moved(mat._location_from_matrix(occ['transform']))
            return box_values(cp._bbox_from_shape(placed))
        value = op_memo.memoized_value(OP, args, compute)
        if type(value) not in (tuple, list):
            raise Fallback('unsupported cached bounds value')
        box_values({'min': value[:3], 'max': value[3:]})
        boxes.append(value)
    # Preserve the original traversal order, including signed-zero ties.
    return {'min': [min(v[a] for v in boxes) for a in range(3)],
            'max': [max(v[a] for v in boxes) for a in range(3, 6)]}

def exact(box):
    values = box_values(box)
    return {'json': json.dumps(box, sort_keys=True, separators=(',', ':'), allow_nan=False),
            'bits': struct.pack('<6d', *values).hex()}

def control(descriptor):
    return cp._bbox_from_shape(mat.materialize_descriptor(descriptor))

def stamp():
    return {str(p.relative_to(HERE/'packages/cadgen/src/cadgen')): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in (HERE/'packages/cadgen/src/cadgen').rglob('*.py')}

def one_case(name, shape):
    tree, _, _ = build_tree_from_compound(shape, root_name=name)
    return name, tree

def run():
    start = time.monotonic()
    before = stamp(); assert before == SETUP['pythonFiles']
    cases = [('planetary', SETUP['planetaryTree'])]
    cases.append(one_case('holes', bd.Compound(children=[bd.Box(20, 14, 3)-bd.Cylinder(2, 10), bd.Box(3, 4, 5).moved(bd.Location((24, 0, 0)))])))
    nurbs = bd.Solid(BRepBuilderAPI_NurbsConvert(bd.Cylinder(7.5, 4).wrapped, True).Shape())
    cases.append(one_case('rotated_curved', bd.Compound(children=[nurbs.moved(bd.Location((3, -4, 5), (23, 41, 17))), bd.Sphere(3).moved(bd.Location((-10, 7, 2), (9, 7, 11)))])))
    cases.append(one_case('native_nested_component', bd.Compound(obj=[bd.Box(3, 5, 7).moved(bd.Location((2, 4, 6))), bd.Cylinder(2, 6).moved(bd.Location((-4, 8, 2), (15, 19, 23)))]).moved(bd.Location((12, -3, 8), (23, 41, 17)))))
    shared = bd.Box(3, 5, 7)
    cases.append(one_case('repeated_instances', bd.Compound(children=[shared.moved(bd.Location((0, 0, 0))), shared.moved(bd.Location((0, 0, 0))), shared.moved(bd.Location((20, 0, 0), (13, 27, 41)))])))
    tolerant = bd.Box(4, 6, 8)
    BRep_Builder().UpdateVertex(tolerant.vertices()[0].wrapped, .05)
    cases.append(one_case('mixed_tolerances', bd.Compound(children=[tolerant, bd.Cylinder(2, 3).moved(bd.Location((30, 3, -4)))])))
    cases.append(one_case('mirrored_nested_groups', bd.Compound(children=[bd.Compound(children=[nurbs.moved(bd.Location((4, 7, 2), (10, 20, 30))), bd.Box(3, 5, 7).mirror(bd.Plane.YZ)]).moved(bd.Location((9, -8, 7), (7, 13, 19)))])))
    rows = ROWS
    for name, tree in cases:
        descriptor = read_snapshot(tree)
        t = time.perf_counter(); wanted = control(descriptor); control_ms = (time.perf_counter()-t)*1000
        for state in ('cold-key', 'ram', 'disk'):
            if state == 'disk': op_memo.clear()
            computes = COUNT['computes']; t = time.perf_counter(); got = candidate(descriptor); ms=(time.perf_counter()-t)*1000
            parity = exact(got) == exact(wanted)
            rows.append({'case': name, 'state': state, 'parity': parity, 'control': exact(wanted), 'candidate': exact(got), 'controlMs': control_ms, 'candidateMs': ms, 'computes': COUNT['computes']-computes})
            if not parity:
                raise AssertionError(f'EXACT BOUNDS MISMATCH: {name}/{state}')
    descriptor = read_snapshot(cases[0][1])
    original = copy.deepcopy(descriptor)
    checks = CHECKS
    # Root/linked tree reads belong to the verified descriptor capture, which
    # precedes this measurement helper rather than being inferred from an index.
    path=object_path(cases[0][1]);data=path.read_bytes()
    for damage in ('missing', 'corrupt'):
        try:
            if damage == 'missing':path.unlink()
            else:path.write_bytes(b'not-the-captured-tree')
            try:read_snapshot(cases[0][1])
            except (OSError, ValueError):checks[f'root_tree_{damage}_rejects_snapshot']=True
            else:raise AssertionError(f'tree/{damage} hidden')
        finally:path.write_bytes(data)
    first = next(iter(descriptor['components'].values()))
    for kind in ('brep', 'surf'):
        path = object_path(first[kind]); data=path.read_bytes()
        for damage in ('missing','corrupt'):
            try:
                if damage == 'missing': path.unlink()
                else: path.write_bytes(b'wrong-byte-snapshot')
                try: candidate(descriptor)
                except (OSError, ValueError): checks[f'{kind}_{damage}_cannot_hide_behind_ram_hit']=True
                else: raise AssertionError(f'{kind}/{damage} hidden')
            finally: path.write_bytes(data)
        assert exact(candidate(descriptor)) == exact(control(descriptor))
    # Find the actual occurrence for this component, not a coincidental map order.
    cid=next(k for k,v in descriptor['components'].items() if v is first)
    occ=next(o for o in descriptor['occurrences'] if o['component']==cid)
    args=key_args(first,occ['transform'])
    index=index_dir('op')/op_memo._op_index_key(op_memo._build_key(OP,args,{}))
    index.write_text('{broken-json')
    op_memo.clear(); before_compute=COUNT['computes']; candidate(descriptor)
    checks['malformed_op_entry_recomputed']=COUNT['computes']>before_compute
    before_compute=COUNT['computes']; op_memo.clear(); index.unlink(); candidate(descriptor)
    checks['deleted_op_entry_recomputed']=COUNT['computes']>before_compute
    index.write_text(json.dumps({'value': None}));op_memo.clear()
    try:candidate(descriptor)
    except Fallback:checks['unsupported_cached_value_falls_back']=True
    else:raise AssertionError('unsupported cache value admitted')
    index.unlink();op_memo.clear();candidate(descriptor)
    bad=copy.deepcopy(descriptor);bad['occurrences'][0]['transform'][0]=float('nan')
    try:candidate(bad)
    except Fallback:checks['nonfinite_transform_falls_back']=True
    else:raise AssertionError('nonfinite transform admitted')
    bad=copy.deepcopy(descriptor);bad['assembly']['root']['children']=[]
    try:candidate(bad)
    except Fallback:checks['unsupported_hierarchy_falls_back']=True
    else:raise AssertionError('unsupported hierarchy admitted')
    op_memo.clear()
    with mock.patch.object(cp,'_bbox_from_shape',return_value=None):
        fresh=copy.deepcopy(descriptor);fresh['occurrences'][0]['transform'][3]+=123.125
        try:candidate(fresh)
        except Fallback:checks['missing_bounds_falls_back']=True
        else:raise AssertionError('partial bounds admitted')
    assert original == descriptor
    assert stamp()==before
    roots={str(Path(m.__file__).resolve()) for name,m in sys.modules.items() if name.startswith('cadgen') and getattr(m,'__file__',None)}
    assert all(str(HERE/'packages/cadgen/src/cadgen') in p for p in roots)
    result={'scope':'Private canonical BREP + full-placement bounds parity, no production publication reordering', 'qualification':'Functional stage observations only; no isolated performance claim. All CAD/store writes are under models/tmp. Archived and current runtime sources are unchanged.', 'elapsedSeconds':time.monotonic()-start, 'rows':rows, 'checks':checks, 'sourceFiles':before,'modulePaths':sorted(roots), 'helper':Path(__file__).read_text(), 'setup':SETUP}
    path=Path(SETUP['artifacts'])/'result.json';path.write_text(json.dumps(result,indent=2,allow_nan=False))
    print(json.dumps({'result':str(path),'cases':len(cases),'exactParityRows':len(rows),'checks':checks,'elapsedSeconds':result['elapsedSeconds']}))

if __name__=='__main__':
    try:
        run()
    except Exception as error:
        failure={'errorType':type(error).__name__,'error':str(error),'rows':ROWS,'checks':CHECKS,
                 'helper':Path(__file__).read_text(),'setup':SETUP,
                 'qualification':'Private functional probe; partial result, not performance evidence.'}
        path=Path(SETUP['artifacts'])/'failure.json'
        path.write_text(json.dumps(failure,indent=2,allow_nan=False))
        raise
